// --- B2: Write sequence ---
reg new_bw;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        m_wr_pnt <= {BD_WIDTH{1'b0}};
        wr_cnt   <= {BD_WIDTH{1'b0}};
        new_bw   <= 1'b0;
    end else begin
        new_bw <= 1'b0;

        if (we_m && (free_bd > {BD_WIDTH{1'b0}})) begin
            case (m_wr_pnt)
                0: bd_mem_0 <= dat_in_m;
                1: bd_mem_1 <= dat_in_m;
                2: bd_mem_2 <= dat_in_m;
                3: bd_mem_3 <= dat_in_m;
                4: bd_mem_4 <= dat_in_m;
                5: bd_mem_5 <= dat_in_m;
                6: bd_mem_6 <= dat_in_m;
                7: bd_mem_7 <= dat_in_m;
                default: bd_mem_0 <= dat_in_m;
            endcase

            if (m_wr_pnt == (BD_SIZE - 1)) begin
                m_wr_pnt <= {BD_WIDTH{1'b0}};
            end else begin
                m_wr_pnt <= m_wr_pnt + 1'b1;
            end

            if (MODE_16BIT != 1'b0) begin
                if (wr_cnt == 3) begin
                    new_bw  <= 1'b1;
                    wr_cnt  <= {BD_WIDTH{1'b0}};
                end else begin
                    wr_cnt  <= wr_cnt + 1'b1;
                end
            end else begin
                if (wr_cnt == 1) begin
                    new_bw  <= 1'b1;
                    wr_cnt  <= {BD_WIDTH{1'b0}};
                end else begin
                    wr_cnt  <= wr_cnt + 1'b1;
                end
            end
        end
    end
end

// --- B5: Release edge detect and free_bd update ---
always @(posedge clk or posedge rst) begin
    if (rst) begin
        free_bd    <= FREE_BD_INIT;
        last_a_cmp <= 1'b0;
    end else begin
        if (new_bw) begin
            free_bd <= free_bd - 1'b1;
        end else if ((a_cmp == 1'b1) && (last_a_cmp == 1'b0)) begin
            free_bd <= free_bd + 1'b1;
            last_a_cmp <= 1'b1;
        end else begin
            last_a_cmp <= a_cmp;
        end
    end
end

